import type { CapacitorConfig } from '@capacitor/cli';

// iOS shell for the same Nuxt app the Electrobun desktop shell wraps (copland.obol family).
const config: CapacitorConfig = {
  appId: 'copland.obol.mobile',
  appName: 'Obol',
  // Static Nuxt SPA generated by `npm run ios:generate` (OBOL_DESKTOP_STATIC=true):
  // hash routing + relative asset baseURL. Nuxt writes `.output/public`; copying that
  // directory avoids relying on a local `dist` symlink.
  webDir: '.output/public'
};

export default config;
